      "alternatives": [
        "(df['f02'] == 'tcp') | ((df['f20'] == 0) & (df['f21'] == 0) & (df['f22'] == 0) & (df['f23'] == 0) & (df['f24'] == 0) & (df['f25'] == 0) & (df['f26'] == 0))"
