    {
      "id": "R3",
      "category": "protocol",
      "alternatives": [
        "(df['f03'] == 'http') | ((df['f29'] == 0) & (df['f30'] == 0) & (df['f39'] == 0))"
      ],
      "features": ["f03", "f29", "f30", "f39"],
      "rationale": "HTTP-specific fields should be zero for non-HTTP flows."
    },
    {
      "id": "R4",
      "category": "protocol",
      "alternatives": [
        "(df['f03'] == 'ftp') | ((df['f37'] == 0) & (df['f38'] == 0))"
      ],
      "features": ["f03", "f37", "f38"],
      "rationale": "FTP-specific fields should be zero for non-FTP flows."
    },
    {
      "id": "R5",
      "category": "protocol",
      "alternatives": [
        "(df['f02'] != 'udp') | (~df['f03'].isin(['http', 'ftp', 'smtp', 'ssh', 'ftp-data', 'irc']))"
      ],
      "features": ["f02", "f03"],
      "rationale": "UDP does not support TCP-based application protocols."
    }
  ]
}
